SINA_SMART["physio1-small-intestine-motility"] = {"lecture":"physio1-small-intestine-motility","title":"Small intestine motility","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physio1-small-intestine-motility:e0","text":"Small intestine: 5-6 m (duodenum 25 cm, jejunum ~2 m, ileum ~3 m).","topic":"Reminders","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-small-intestine-motility:e1","text":"Myenteric plexus: motility. Submucosal plexus: secretion.","topic":"Reminders","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-small-intestine-motility:e2","text":"Vagus stimulates (ACh); sympathetic inhibits (noradrenaline).","topic":"Reminders","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-small-intestine-motility:e3","text":"MMC every 90-120 min; motilin starts it; food stops it.","topic":"Fasting state: the MMC","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-small-intestine-motility:e4","text":"Phase III clears residue and bacteria (housekeeper).","topic":"Fasting state: the MMC","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-small-intestine-motility:e5","text":"Segmentation mixes (ENS, CCK); peristalsis propels (5-HT, ACh, substance P).","topic":"Fed state","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-small-intestine-motility:e6","text":"Loss of MMC → bacterial overgrowth.","topic":"Disorders","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-small-intestine-motility:e7","text":"Ileus: absent motility after surgery or with low K⁺.","topic":"Disorders","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"3wgqkz":"a","1w28hzt":"a","14vqs4v":"a","18l8stl":"a","112njb8":"a","1opdtyv":"a","1w9x5bx":"a","9nkzck":"a","bp35i1":"a","u6o3dd":"a","wyz81u":"a","126cld9":"a","eqdql2":"a"},"mapCounts":{"verified":0,"auto":13,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physio1-small-intestine-motility:e0":{"s":0,"u":["Small intestine: 5-6 m (duodenum 25 cm, jejunum ~2 m, ileum ~3 m).","The small intestine is 5-6 m long, 75-80% of the digestive tract: duodenum (25 cm), jejunum (about 2 m) and ileum (about 3 m), which ends at the ileocaecal valve ."],"dp":[]},"physio1-small-intestine-motility:e1":{"s":0,"u":["Myenteric plexus: motility. Submucosal plexus: secretion.","It is controlled by the enteric nervous system : the myenteric (Auerbach) plexus between the longitudinal and circular layers (motor control) and the submucosal (Meissner) plexus (secretion and sensory role)."],"dp":[]},"physio1-small-intestine-motility:e2":{"s":0,"u":["Vagus stimulates (ACh); sympathetic inhibits (noradrenaline).","Extrinsic nerves modulate it: sympathetic (splanchnic nerves, noradrenaline) inhibits; parasympathetic (vagus, ACh) stimulates, mainly proximally."],"dp":[]},"physio1-small-intestine-motility:e3":{"s":1,"u":["MMC every 90-120 min; motilin starts it; food stops it.","Motilin from M cells of the duodenum starts the MMC; food intake suppresses it ."],"dp":[]},"physio1-small-intestine-motility:e4":{"s":1,"u":["Phase III clears residue and bacteria (housekeeper).","Phase III : intense, regular contractions that migrate down the gut, clearing undigested residue and bacteria (the housekeeper) and preparing for the next meal.","Phase II : irregular contractions of increasing strength."],"dp":[{"h":"Why hunger rumbles","t":"The loud gurgling of an empty stomach (borborygmi) is largely MMC phase III: strong contractions pushing gas and fluid through an empty gut. Motilin peaks coincide with hunger sensations, and the MMC restarts a few hours after each meal. It is one reason nutritionists sometimes recommend not snacking constantly: the gut needs fasting periods to run its housekeeper wave."}]},"physio1-small-intestine-motility:e5":{"s":2,"u":["Segmentation mixes (ENS, CCK); peristalsis propels (5-HT, ACh, substance P).","Segmentation : rhythmic, localised contractions of the circular muscle that divide and re-mix chyme without moving it far, increasing contact with the mucosa; regulated by the ENS and CCK .","Peristalsis : coordinated waves that move chyme aborally : the circular muscle contracts behind the bolus while the segment ahead relaxes (the law of the intestine), mediated by serotonin (5-HT) , ACh and substance P (contraction) with NO and VIP (relaxation)."],"dp":[]},"physio1-small-intestine-motility:e6":{"s":3,"u":["Loss of MMC → bacterial overgrowth.","Intestinal dysmotility (reduced motility): bloating and small intestinal bacterial overgrowth , because the MMC no longer clears bacteria."],"dp":[]},"physio1-small-intestine-motility:e7":{"s":3,"u":["Ileus: absent motility after surgery or with low K⁺.","Ileus : loss of motility after surgery, with electrolyte disturbances (low K⁺) or neurological impairment; it causes distension and vomiting without mechanical obstruction."],"dp":[]}},"meta":{"3wgqkz":{"a":"recall","vg":"physio1-small-intestine-motility:e3/recall/1"},"1w28hzt":{"a":"recall","vg":"physio1-small-intestine-motility:e3/recall/2"},"14vqs4v":{"a":"recall","vg":"physio1-small-intestine-motility:e4/recall/1"},"18l8stl":{"a":"recall","vg":"physio1-small-intestine-motility:e6/recall/1"},"112njb8":{"a":"recall","vg":"physio1-small-intestine-motility:e5/recall/1"},"1opdtyv":{"a":"recall","vg":"physio1-small-intestine-motility:e5/recall/2"},"1w9x5bx":{"a":"recall","vg":"physio1-small-intestine-motility:e1/recall/1"},"9nkzck":{"a":"recall","vg":"physio1-small-intestine-motility:e2/recall/1"},"bp35i1":{"a":"recall","vg":"physio1-small-intestine-motility:e5/recall/3"},"u6o3dd":{"a":"recall","vg":"physio1-small-intestine-motility:e6/recall/2"},"wyz81u":{"a":"recall","vg":"physio1-small-intestine-motility:e7/recall/1"},"126cld9":{"a":"recall","vg":"physio1-small-intestine-motility:e0/recall/1"},"eqdql2":{"a":"recall","vg":"physio1-small-intestine-motility:e6/recall/3"}},"explRev":"307ee089f998"};
